    adcs_vec3_t nb1, nb2, nr1, nr2;
    adcs_vec3_t c1, c2;
    double body_sep, inert_sep;

    if (b1 == NULL || b2 == NULL || r1 == NULL || r2 == NULL ||
        body_angle == NULL || inertial_angle == NULL || mismatch == NULL) {
        return ADCS_E_NULL;
    }

    if (adcs_vec3_normalize(b1, ADCS_EPS_NORM, &nb1) != ADCS_OK ||
        adcs_vec3_normalize(b2, ADCS_EPS_NORM, &nb2) != ADCS_OK ||
        adcs_vec3_normalize(r1, ADCS_EPS_NORM, &nr1) != ADCS_OK ||
        adcs_vec3_normalize(r2, ADCS_EPS_NORM, &nr2) != ADCS_OK) {
        *body_angle = INFINITY;
        *inertial_angle = INFINITY;
        *mismatch = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    c1 = adcs_vec3_cross(&nb1, &nb2);
    c2 = adcs_vec3_cross(&nr1, &nr2);
    if (adcs_vec3_norm(&c1) <= ADCS_EPS_COLLINEAR ||
        adcs_vec3_norm(&c2) <= ADCS_EPS_COLLINEAR) {
        *body_angle = INFINITY;
        *inertial_angle = INFINITY;
        *mismatch = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    body_sep = atan2(adcs_vec3_norm(&c1), adcs_vec3_dot(&nb1, &nb2));
    inert_sep = atan2(adcs_vec3_norm(&c2), adcs_vec3_dot(&nr1, &nr2));

    *body_angle = body_sep;
    *inertial_angle = inert_sep;
    *mismatch = fabs(body_sep - inert_sep);
    return ADCS_OK;
}
}

